def find_max(arr):
    if len(arr) == 0:
        return 'Error'

    max_value = arr[0]
    for value in arr:
        if value > max_value:
            max_value = value

    return max_value

print(find_max([32, 45, 28, 47, 39]))

def find_min(arr):
    if len(arr) == 0:
        return 'Error'

    min_value = arr[0]
    for value in arr:
        if value < min_value:
            min_value = value

    return min_value

print(find_min([3, 1, 9, 2]))

def count_evens(arr):
    count = 0

    for value in arr:
        if value % 2 == 0:
            count += 1

    return count

print(count_evens([1, 2, 3, 4, 5, 6]))

def has_pair_sum(arr, target):
    for i in range(len(arr)):
        for j in range(i + 1, len(arr)):
            if arr[i] + arr[j] == target:
                return True

    return False

print(has_pair_sum([2, 4, 7, 11], 13))
